@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .

chemrof:ChemicalSimilarity a sh:NodeShape ;
    sh:targetClass chemrof:ChemicalSimilarity ;
    sh:closed true ;
    sh:name "similarity" ;
    sh:ignoredProperties ( rdf:type ) ;
    sh:property [
        sh:path chemrof:owl_subclass_of ;
        sh:name "owl subclass of" ;
        sh:class owl:Class ;
        sh:maxCount 1 ;
        sh:nodeKind sh:BlankNode ;
        sh:order 0
    ] .

